      "properties": {
        "value": {
          "oneOf": [
            {"type": "number"},
            {
              "type": "string",
              "enum": [
                "not applicable",
                "not collected",
                "not provided",
                "restricted access"
              ]
            }
          ]
        },
        "units": {
          "type": "string",
          "enum": [
            "minutes",
            "hours",
            "days",
            "weeks",
            "months",
            "years",
